ValidationRule.errorConditionFormula:
AND(
 NOT(
  ISBLANK(Next_Starting_Term__c)
 ),
 OR(
  AND(
   NOT(
    ISBLANK(hed__Start_Date__c)
   ),
   Next_Starting_Term__r.hed__Start_Date__c < hed__Start_Date__c
  ),
  AND(
   NOT(
    ISBLANK(hed__End_Date__c)
   ),
   Next_Starting_Term__r.hed__End_Date__c > hed__End_Date__c
  )
 )
)
